const intake = $('Normalize Intake Data').first().json;
const personSearch = $('Is Person by Email Found?').first().json;
const lead = $('Get Existing Lead').first().json;
const llmStructuredResponse = $('Analyze & Classify Enquiry').first().json;
const histContext = $('Clean HTML to Text').first().json;

// 1. Raw Data Extraction
const crmPerson = personSearch.data?.items?.[0]?.item || {};
// const rawCrmName = crmPerson.name || '';
const rawCrmOrg = crmPerson.organization?.name || crmPerson.organization || '';

// const intakeFirstName = intake.contact_first_name || '';
// const intakeLastName = intake.contact_last_name || '';
// const rawIntakeName = `${intakeFirstName} ${intakeLastName}`.trim();
const rawIntakeOrg = intake.organization_name || '';

// 2. Cleaned Strings for Comparison
// const cleanCrmName = rawCrmName.toLowerCase().replace(/\s+/g, '');
// const cleanIntakeName = `${intakeFirstName}${intakeLastName}`.toLowerCase().replace(/\s+/g, '');

const warnings = [];

// ---------------------------------------------------------------------------
// CONDITION 1: NAME DISCREPANCY
// ---------------------------------------------------------------------------
// if (cleanIntakeName !== cleanCrmName) {
//   warnings.push(
// `⚠️ *NAME REVIEW REQUIRED*

// A name discrepancy was detected for this contact.

// • Existing name: ${rawCrmName || 'not specified'}
// • Supplied name: ${rawIntakeName || 'not specified'}

// No contact name was changed automatically.`
//   );
// }

// ---------------------------------------------------------------------------
// CONDITION 1: ORGANIZATION DISCREPANCY (Strict OR Logic)
// ---------------------------------------------------------------------------
// const crmHasOrg = !!crmPerson.organization;
// const intakeHasOrg = !!intake.organization_name;
const cleanCrmOrg = rawCrmOrg.toLowerCase().replace(/\s+/g, '');
const cleanIntakeOrg = rawIntakeOrg.toLowerCase().replace(/\s+/g, '');


if (cleanCrmOrg !== cleanIntakeOrg) {
  warnings.push(
`⚠️ *ORGANIZATION REVIEW REQUIRED*
Normalize Intake Data
An organization discrepancy was detected for this contact.

• Existing organization: ${rawCrmOrg || 'not specified'}
• Supplied organization: ${rawIntakeOrg || 'not specified'}

No organization relationship was changed automatically.`
  );
}

// ---------------------------------------------------------------------------
// CONDITION 2: PERSON PHONE UPDATE DETECTED
// ---------------------------------------------------------------------------
const intakePhone = intake.contact_phone || '';
const crmPhone = crmPerson.phones?.[0] || crmPerson.phone || '';
const shouldUpdatePerson = intakePhone !== '' && intakePhone !== crmPhone;

if (shouldUpdatePerson) {
  warnings.push(
`ℹ️ *PERSON RECORD UPDATE*

A new phone number was provided and will be updated in Pipedrive.

• Existing phone: ${crmPhone || 'not specified'}
• Supplied phone: ${intakePhone}`
  );
}

// ---------------------------------------------------------------------------
// CONDITION 3: LEAD TITLE / ENQUIRY UPDATE DETECTED
// ---------------------------------------------------------------------------
const originalMessage = histContext?.clean_original_message || '';
const intakeEnquiryDescription = intake?.enquiry_description || '';
const orgMsg = originalMessage.toLowerCase().replace(/\s+/g, ' ').trim();
const inEnqDesc = intakeEnquiryDescription.toLowerCase().replace(/\s+/g, ' ').trim();
const shouldUpdateLeadEnquiry = orgMsg !== inEnqDesc;

if (shouldUpdateLeadEnquiry) {
  warnings.push(
`ℹ️ *LEAD RECORD UPDATE*

A new enquiry type was provided and lead record will be updated in Pipedrive.

• Existing enquiry: ${originalMessage|| 'not specified'}
• Supplied enquiry: ${intakeEnquiryDescription || 'not specified'}`
  );
}

// ---------------------------------------------------------------------------
// STACK ALL TRIGGERED WARNINGS / NOTICES
// ---------------------------------------------------------------------------
const notificationContext = warnings.length > 0
  ? warnings.join('\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n')
  : '';

return {
  json: {
    ...$input.first().json,
    notification_context: notificationContext,
    should_update_person: shouldUpdatePerson,
    should_update_lead: shouldUpdateLeadEnquiry
  }
};

