parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "is_genuine_enquiry": {
      "type": "boolean",
      "description": "Whether the message appears to be a genuine business enquiry rather than spam, gibberish, or irrelevant content."
    },
    "summary": {
      "type": "string",
      "description": "A concise summary of what the client is asking about."
    },
    "requirements": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "requirement": {
            "type": "string",
            "description": "A single distinct need, problem, or goal mentioned by the client."
          },
          "deadline_raw": {
            "anyOf": [{ "type": "string" }, { "type": "null" }],
            "description": "The deadline or timeframe for this specific requirement, exactly as the client expressed it. Use null if no deadline was mentioned for this item."
          },
          "resolved_deadline": {
            "anyOf": [
              { "type": "string", "format": "date-time" },
              { "type": "null" }
            ],
            "description": "This requirement's deadline converted to ISO-8601 date-time, using the current date/time provided in the enquiry as the anchor. Use null if no deadline was mentioned for this item, or if it's too vague to convert reliably."
          }
        },
        "required": ["requirement", "deadline_raw", "resolved_deadline"],
        "additionalProperties": false
      },
      "description": "The client's identified needs, problems, goals, or requirements, each with its own deadline if one was given."
    },
    "client_requested_actions": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "description": "A specific action the client explicitly asked the business to take."
          },
          "deadline_raw": {
            "anyOf": [{ "type": "string" }, { "type": "null" }],
            "description": "The deadline or timeframe for this specific requested action, exactly as the client expressed it. Use null if none was mentioned for this item."
          },
          "resolved_deadline": {
            "anyOf": [
              { "type": "string", "format": "date-time" },
              { "type": "null" }
            ],
            "description": "This action's deadline converted to ISO-8601 date-time, using the current date/time provided in the enquiry as the anchor. Use null if no deadline was mentioned for this item, or if it's too vague to convert reliably."
          }
        },
        "required": ["action", "deadline_raw", "resolved_deadline"],
        "additionalProperties": false
      },
      "description": "Specific actions the client explicitly asked the business to take, each with its own deadline if one was given. Use an empty array if no specific action was requested."
    },
    "suggested_next_actions": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Reasonable next actions suggested from the enquiry. These are suggestions only and should not be treated as actions that have already been executed. Deadlines are not tracked here — refer to the requirement or requested action a suggestion relates to."
    },
    "information_gaps": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Important information that appears to be missing from the enquiry and may be useful for handling it."
    },
    "lead_title": {
      "type": "string",
      "description": "A concise title for representing this enquiry as a lead."
    },
    "confidence_level": {
      "type": "string",
      "enum": ["high", "medium", "low"],
      "description": "Confidence in the accuracy and completeness of the extracted information."
    },
    "confidence_reasoning": {
      "type": "string",
      "description": "A brief explanation of why the extraction confidence is high, medium, or low."
    }
  },
  "required": [
    "is_genuine_enquiry", "summary", "requirements", "client_requested_actions",
    "suggested_next_actions", "information_gaps", "lead_title",
    "confidence_level", "confidence_reasoning"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Access the nested LLM output correctly
const analysis = $input.first().json.output || {};

const reasons = [];

// Confidence check
if (analysis.confidence_level === 'low') {
  reasons.push("⚠️ Low Confidence Score: The model could not confidently process this enquiry.");
}

// Genuine enquiry check
if (analysis.is_genuine_enquiry === false) {
  reasons.push("🚫 Spam or Gibberish Detected: The enquiry was flagged as non-genuine.");
}

// Business-logic checks — only meaningful when it's actually a genuine enquiry
if (analysis.is_genuine_enquiry === true) {
  const noRequirements = (analysis.requirements || []).length === 0;
  const noGaps = (analysis.information_gaps || []).length === 0;
  if (noRequirements && noGaps) {
    reasons.push("❓ Empty Extraction: Marked genuine but nothing was extracted and nothing was flagged as missing.");
  }

  if ((analysis.suggested_next_actions || []).length === 0) {
    reasons.push("🕳️ No Next Action: Genuine enquiry has no suggested next action.");
  }

  if (!analysis.lead_title || analysis.lead_title.trim().length === 0) {
    reasons.push("🏷️ Missing Lead Title.");
  }
}

// Self-contradiction check
// if (analysis.confidence_level === 'high' && (analysis.information_gaps || []).length > 0) {
//   reasons.push("⚠️ Confidence Mismatch: Marked high confidence but information gaps were listed.");
// }

const errorReason = reasons.length > 0 ? reasons.join('\n') : null;

// ALWAYS return an object so downstream nodes can see the schema
return [{
  json: {
    ...analysis,
    error_reason: errorReason,
    has_error: errorReason !== null,
    review_reasons: reasons
  }
}];
